BEGIN;
create temp table checks(label text);
create function pg_temp.check(passed boolean,label text) returns void language plpgsql as $$begin
 if passed is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table blocked_requests(id uuid);
create function pg_temp.reject_fixture_event() returns trigger language plpgsql as $$begin
 if exists(select 1 from blocked_requests where id=new.id) then raise exception 'fixture recording unavailable' using errcode='P0002';end if;return new;end$$;
create trigger fixture_event_failure before insert on public.shared_action_events for each row execute function pg_temp.reject_fixture_event();
DO $$
declare p uuid:=gen_random_uuid();l uuid:=gen_random_uuid();l2 uuid:=gen_random_uuid();actor uuid;booking_req uuid:=gen_random_uuid();r jsonb;again jsonb;input jsonb;t uuid;job uuid;token uuid;email uuid;sms uuid;w jsonb;definition uuid:=gen_random_uuid();slot uuid:=gen_random_uuid();n integer;
begin
 select id into actor from public.profiles where org_id='22222222-2222-2222-2222-222222222222' order by id limit 1;
 insert into public.properties(id,name,org_id,settings)values(p,'Console booking fixture','22222222-2222-2222-2222-222222222222','{"timezone":"America/Los_Angeles"}');
 insert into public.leads(id,property_id,first_name,status,email,phone,crm_sync_status,crm_sync_next_retry_at)values(l,p,'Booking fixture','new','booking@example.invalid','+15550000000','processing',now()+interval '1 hour'),(l2,p,'Other fixture','leased',null,null,'pending',now());
 insert into public.workflow_definitions(id,property_id,name,trigger_on,steps,exit_conditions,is_active)values(definition,p,'Stop when booked','lead_created','[{"action":"wait","delay_hours":1}]','["tour_booked"]',true);
 insert into public.lead_workflows(lead_id,workflow_id,status,next_action_at)values(l,definition,'paused',now()+interval '1 hour');
 input:=jsonb_build_object('date',current_date+3,'time','10:00','type','in_person','sendConfirmation',true,'notes','Private booking notes','assignedAgentId',null);
 perform pg_temp.check(public.book_recorded_console_tour(p,l,gen_random_uuid(),booking_req,input)->>'state'='forbidden','actor scope required');
 perform pg_temp.check(public.book_recorded_console_tour(p,gen_random_uuid(),actor,booking_req,input)->>'state'='not_found','lead scope required');
 r:=public.book_recorded_console_tour(p,l,actor,booking_req,input);t:=(r->'tour'->>'id')::uuid;job:=(r->>'confirmationWorkId')::uuid;
 perform pg_temp.check(r->>'state'='applied' and r->>'confirmation'='queued','booking queues confirmation without claiming send');
 perform pg_temp.check(public.tour_calendar_schedules(p,l)->0->>'startsAt'=public.tour_reminder_schedule(p,'tours',t)->>'startsAt','calendar preview resolves the same property instant as confirmations');
 perform pg_temp.check(jsonb_array_length(public.tour_calendar_schedules(p,gen_random_uuid()))=0,'calendar preview cannot cross lead scope');
 perform pg_temp.check(jsonb_array_length(public.tour_calendar_schedules(gen_random_uuid(),l))=0,'calendar preview cannot cross property scope');
 perform pg_temp.check((select schedule_version=1 and created_by=actor and confirmation_sent_at is null from public.tours where id=t),'tour saved once with operator and no false delivery marker');
 perform pg_temp.check((select status='tour_booked' and crm_sync_status='processing' and crm_sync_next_retry_at=now()+interval '1 hour' from public.leads where id=l),'booking updates lead without stealing CRM lease');
 perform pg_temp.check((select status='stopped' and next_action_at is null from public.lead_workflows where lead_id=l and workflow_id=definition),'booking stops paused prospecting follow-up');
 perform pg_temp.check((select count(*)=1 from public.lead_activities where lead_id=l and type='tour_booked'),'one attributed booking activity');
 perform pg_temp.check((select count(*)=2 from public.tour_reminder_channels where work_id=job and state='queued' and attempts=0),'email and SMS independently queued before any attempt');
 perform pg_temp.check((select action='tour.booked' and actor_id=actor and after_state->>'status'='scheduled' and not training_eligible from public.shared_action_events where id=booking_req),'booking decision recorded and excluded from training');
 perform pg_temp.check((select position('Private booking notes' in to_jsonb(e)::text)=0 from public.shared_action_events e where id=booking_req),'booking history does not duplicate notes');
 again:=public.book_recorded_console_tour(p,l,actor,booking_req,input);
 perform pg_temp.check(again->>'state'='replayed' and again->'tour'->>'id'=t::text,'lost-response retry recovers the same booking');
 perform pg_temp.check((select count(*)=1 from public.tours where lead_id=l) and (select count(*)=1 from public.shared_action_events where property_id=p),'retry adds no tour or event');
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,booking_req,input||'{"time":"11:00"}')->>'state'='request_conflict','successful identity cannot change its booking_req');
 perform pg_temp.check(public.book_recorded_console_tour(p,l2,actor,gen_random_uuid(),input)->>'state'='unavailable','overlapping reservation cannot overbook');
 perform pg_temp.check((select count(*)=0 from public.tours where lead_id=l2),'capacity failure leaves no tour');
 perform pg_temp.check(exists(select 1 from jsonb_array_elements(public.pending_tour_reminders(p)->'candidates') x where x->>'tourId'=t::text and x->>'kind'='confirmation'),'future booking confirmation is due now, outside reminder date window');
 w:=public.prepare_tour_reminder(p,'tours',t,1,'confirmation');token:=(w->>'lease_token')::uuid;
 perform pg_temp.check(jsonb_array_length(w->'channels')=2,'worker claims the saved confirmation');
 perform pg_temp.check(public.claim_tour_legacy_delivery(p,'tours',t,1,'confirmation') is null,'legacy grouped sender cannot bypass per-channel state');
 select id into email from public.tour_reminder_channels where work_id=job and channel='email';select id into sms from public.tour_reminder_channels where work_id=job and channel='sms';
 perform public.start_tour_reminder_channel(email,token,'Fixture email','Tour confirmation','sender@example.invalid');
 perform public.finish_tour_reminder_channel(email,token,'local-email-receipt');
 perform public.start_tour_reminder_channel(sms,token,'Fixture SMS',null,'+15550000001');perform public.finish_tour_reminder_channel(sms,token,null);
 perform pg_temp.check(public.settle_tour_reminder(job,token)='review','partial confirmation remains in review');
 perform pg_temp.check((select confirmation_sent_at is null from public.tours where id=t),'partial acceptance cannot mark whole confirmation sent');
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,booking_req,input)->>'confirmation'='review','booking retry reports current confirmation status');
 r:=public.review_recorded_tour_reminder(p,l,sms,actor,gen_random_uuid(),'{"resolution":"not_sent","reason":"Provider confirmed nonacceptance"}');
 perform pg_temp.check(r->>'channelState'='queued','operator can requeue only unaccepted confirmation channel');
 w:=public.prepare_tour_reminder(p,'tours',t,1,'confirmation');token:=(w->>'lease_token')::uuid;
 perform pg_temp.check(public.start_tour_reminder_channel(email,token,'Fixture email','Tour confirmation','sender@example.invalid') is null,'accepted confirmation email is not repeated');
 perform public.start_tour_reminder_channel(sms,token,'Fixture SMS',null,'+15550000001');perform public.finish_tour_reminder_channel(sms,token,'local-sms-receipt');
 perform pg_temp.check(public.settle_tour_reminder(job,token)='completed','whole confirmation completes only after both receipts');
 perform pg_temp.check((select confirmation_sent_at is not null from public.tours where id=t),'complete acceptance marker saved');
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,booking_req,input)->>'confirmation'='accepted','booking retry reports confirmed provider acceptance');
 -- Shared slots can hold more than one reservation when explicitly configured.
 insert into public.tour_slots(id,property_id,slot_date,start_time,end_time,max_bookings,current_bookings,is_available)values(slot,p,current_date+4,'10:00','10:30',2,0,true);
 input:=input||jsonb_build_object('date',current_date+4,'sendConfirmation',false);booking_req:=gen_random_uuid();
 r:=public.book_recorded_console_tour(p,l2,actor,booking_req,input);
 perform pg_temp.check(r->>'state'='applied' and r->>'leadStatus'='leased' and r->>'confirmation'='not_requested','advanced lead state and no-confirmation choice preserved');
 perform pg_temp.check((select slot_id=slot from public.tours where id=(r->'tour'->>'id')::uuid),'booking uses the configured slot');
 again:=public.book_recorded_console_tour(p,l,actor,gen_random_uuid(),input);
 perform pg_temp.check(again->>'state'='applied' and (select current_bookings=2 from public.tour_slots where id=slot),'configured two-tour capacity honored');
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,gen_random_uuid(),input)->>'state'='unavailable','configured capacity cannot be exceeded');
 -- A failed action recording must roll back reservation, lead effects and sends.
 booking_req:=gen_random_uuid();insert into blocked_requests values(booking_req);input:=input||jsonb_build_object('date',current_date+5,'sendConfirmation',true);select count(*) into n from public.tours where property_id=p;
 begin perform public.book_recorded_console_tour(p,l,actor,booking_req,input);raise exception 'FAIL: recorder failure accepted';exception when sqlstate 'P0002' then insert into checks values('recording failure rolls back booking');end;
 perform pg_temp.check((select count(*)=n from public.tours where property_id=p),'failed recording leaves no reservation');
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where id=booking_req),'failed recording leaves no false action');
 delete from blocked_requests where id=booking_req;
 -- Fresh confirmation requests remain bounded; no old confirmations are inferred.
 r:=public.book_recorded_console_tour(p,l,actor,booking_req,input);t:=(r->'tour'->>'id')::uuid;job:=(r->>'confirmationWorkId')::uuid;
 update public.tour_schedule_work set created_at=now()-interval '24 hours' where id=job;
 perform public.recover_tour_reminders();
 perform pg_temp.check((select state='superseded' from public.tour_schedule_work where id=job),'expired unattempted confirmation is not replayed');
 perform pg_temp.check((select count(*)=2 from public.tour_reminder_channels where work_id=job and state='skipped'),'expired channels visibly not sent');
 perform pg_temp.check(public.prepare_tour_reminder(p,'tours',(again->'tour'->>'id')::uuid,1,'confirmation') is null,'booking without confirmation cannot be silently backfilled');
 update public.properties set settings='{}' where id=p;
 r:=public.book_recorded_console_tour(p,l,actor,gen_random_uuid(),input||jsonb_build_object('date',current_date+6));
 perform pg_temp.check(r->>'state'='needs_timezone','missing timezone blocks reservation');
 update public.properties set settings='{"timezone":"America/Los_Angeles"}' where id=p;
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,gen_random_uuid(),input||jsonb_build_object('date',current_date-1))->>'state'='not_future','past property time rejected');
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,gen_random_uuid(),input||jsonb_build_object('date',current_date+95))->>'state'='date_out_of_range','booking horizon bounded');
 perform pg_temp.check(public.book_recorded_console_tour(p,l,actor,gen_random_uuid(),input||jsonb_build_object('assignedAgentId',gen_random_uuid()))->>'state'='invalid_agent','cross-scope agent rejected');
 -- Initial timezone setup is explicit, recoverable and cannot overwrite valid settings.
 update public.properties set settings='{"keep":"value"}' where id=p;booking_req:=gen_random_uuid();
 perform pg_temp.check(public.set_recorded_tour_timezone(p,gen_random_uuid(),booking_req,'UTC')->>'state'='forbidden','timezone change checks actor scope');
 perform pg_temp.check(public.set_recorded_tour_timezone(p,actor,booking_req,'Unknown/Zone')->>'state'='invalid_timezone','invalid timezone cannot be saved');
 insert into blocked_requests values(booking_req);
 begin perform public.set_recorded_tour_timezone(p,actor,booking_req,'America/New_York');raise exception 'FAIL: timezone recording failure accepted';exception when sqlstate 'P0002' then insert into checks values('timezone change rolls back when its record fails');end;
 perform pg_temp.check(public.tour_booking_context(p)->>'timezone' is null,'failed timezone save leaves configuration unchanged');
 delete from blocked_requests where id=booking_req;
 r:=public.set_recorded_tour_timezone(p,actor,booking_req,'America/New_York');
 perform pg_temp.check(r->>'state'='applied' and r->'context'->>'timezone'='America/New_York','timezone setup saves selected property zone');
 perform pg_temp.check((select settings->>'keep'='value' from public.properties where id=p),'timezone update preserves other settings');
 perform pg_temp.check((select action='tour.timezone.set' and before_state->>'timezone' is null and after_state->>'timezone'='America/New_York' from public.shared_action_events where id=booking_req),'timezone before/after recorded');
 perform pg_temp.check(public.set_recorded_tour_timezone(p,actor,booking_req,'America/New_York')->>'state'='replayed','lost timezone response is replayable');
 perform pg_temp.check(public.set_recorded_tour_timezone(p,actor,booking_req,'UTC')->>'state'='request_conflict','timezone request cannot change intent');
 perform pg_temp.check(public.set_recorded_tour_timezone(p,actor,gen_random_uuid(),'UTC')->>'state'='already_configured' and public.tour_booking_context(p)->>'timezone'='America/New_York','initial setup cannot overwrite a valid configured zone');
 perform pg_temp.check(not has_function_privilege('authenticated','public.book_recorded_console_tour(uuid,uuid,uuid,uuid,jsonb)','EXECUTE') and not has_function_privilege('anon','public.tour_booking_context(uuid)','EXECUTE'),'booking functions service-only');
end$$;
select count(*) as passed from checks;
ROLLBACK;
